--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -561,6 +561,22 @@ PlasmoidItem {
         }
     }

+    function launcherActivities(url: url): list<string> {
+        return tasksModel.launcherActivities(url);
+    }
+
+    function addLauncherToActivity(url: url, activity: string): void {
+        if (Plasmoid.immutability !== PlasmaCore.Types.SystemImmutable) {
+            tasksModel.requestAddLauncherToActivity(url, activity);
+        }
+    }
+
+    function removeLauncherFromActivity(url: url, activity: string): void {
+        if (Plasmoid.immutability !== PlasmaCore.Types.SystemImmutable) {
+            tasksModel.requestRemoveLauncherFromActivity(url, activity);
+        }
+    }
