 #include <PlasmaActivities/Stats/Cleaning>
 #include <PlasmaActivities/Stats/ResultSet>
 #include <PlasmaActivities/Stats/Terms>
@@ -155,7 +157,40 @@ QVariantList createAddLauncherActionList(QObject *appletInterface, const KServic
     }

     if (service && ContainmentInterface::mayAddLauncher(appletInterface, ContainmentInterface::TaskManager, service)) {
-        if (!ContainmentInterface::hasLauncher(appletInterface, ContainmentInterface::TaskManager, service)) {
+        const KActivities::Consumer activitiesConsumer;
+        const QStringList activities = activitiesConsumer.activities();
+        const std::optional<QStringList> launcherActivities =
+            activities.count() >= 2 ? ContainmentInterface::taskManagerLauncherActivities(appletInterface, service) : std::nullopt;
+
+        if (launcherActivities) {
+            auto createActivityActionItem = [&launcherActivities](const QString &activity, const QString &label, const QString &icon) {
+                const bool checked = launcherActivities->contains(activity);
+                QVariantMap action =
+                    Kicker::createActionItem(label,
+                                             icon,
+                                             checked ? QStringLiteral("removeFromTaskManagerActivity") : QStringLiteral("addToTaskManagerActivity"),
+                                             activity);
+                action[QStringLiteral("checkable")] = true;
+                action[QStringLiteral("checked")] = checked;
+                return action;
+            };
+
+            const QString currentActivity = activitiesConsumer.currentActivity();
+
+            QVariantList subActions;
+            subActions << createActivityActionItem(QStringLiteral("00000000-0000-0000-0000-000000000000"), i18n("On All Activities"), QString());
+            subActions << createActivityActionItem(currentActivity, i18n("On the Current Activity"), KActivities::Info(currentActivity).icon());
+            subActions << createSeparatorActionItem();
+            for (const QString &activity : activities) {
+                const KActivities::Info info(activity);
+                subActions << createActivityActionItem(activity, info.name(), info.icon());
+            }
+
+            QVariantMap addToTaskManagerAction =
+                Kicker::createActionItem(i18n("Pin to Task Manager"), QStringLiteral("pin"), QStringLiteral("addToTaskManager"));
+            addToTaskManagerAction[QStringLiteral("subActions")] = subActions;
+            actionList << addToTaskManagerAction;
+        } else if (!ContainmentInterface::hasLauncher(appletInterface, ContainmentInterface::TaskManager, service)) {
             QVariantMap addToTaskManagerAction =
                 Kicker::createActionItem(i18n("Pin to Task Manager"), QStringLiteral("pin"), QStringLiteral("addToTaskManager"));
             actionList << addToTaskManagerAction;
