+std::optional<QStringList> ContainmentInterface::taskManagerLauncherActivities(QObject *appletInterface, const KService::Ptr &service)
+{
+    auto *item = taskManagerQuickItem(appletInterface);
+
+    if (!item || !service) {
+        return std::nullopt;
+    }
+
+    QStringList activities;
+    if (!QMetaObject::invokeMethod(item,
+                                   "launcherActivities",
+                                   Q_RETURN_ARG(QStringList, activities),
+                                   Q_ARG(QUrl, QUrl(QLatin1String("applications:") + service->storageId())))) {
+        return std::nullopt;
+    }
+
+    return activities;
+}
+
+void ContainmentInterface::addTaskManagerLauncherToActivity(QObject *appletInterface, const KService::Ptr &service, const QString &activity)
+{
+    if (auto *item = taskManagerQuickItem(appletInterface); item && service) {
+        QMetaObject::invokeMethod(item,
+                                  "addLauncherToActivity",
+                                  Q_ARG(QUrl, QUrl(QLatin1String("applications:") + service->storageId())),
+                                  Q_ARG(QString, activity));
+    }
+}
+
+void ContainmentInterface::removeTaskManagerLauncherFromActivity(QObject *appletInterface, const KService::Ptr &service, const QString &activity)
+{
+    if (auto *item = taskManagerQuickItem(appletInterface); item && service) {
+        QMetaObject::invokeMethod(item,
+                                  "removeLauncherFromActivity",
+                                  Q_ARG(QUrl, QUrl(QLatin1String("applications:") + service->storageId())),
+                                  Q_ARG(QString, activity));
+    }
+}
+
 QObject *ContainmentInterface::screenContainment(QObject *appletInterface)
 {
     if (!appletInterface) {
@@ -259,4 +298,26 @@ Plasma::Applet *ContainmentInterface::findTaskManagerApplet(Plasma::Containment
     return found != applets.cend() ? *found : nullptr;
 }

+QQuickItem *ContainmentInterface::taskManagerQuickItem(QObject *appletInterface)
+{
+    if (!appletInterface) {
+        return nullptr;
+    }
+
+    auto *applet = appletInterface->property("_plasma_applet").value<Plasma::Applet *>();
+    Plasma::Containment *containment = applet->containment();
+
+    if (!containment || containment->pluginMetaData().pluginId() != QLatin1String("org.kde.panel")) {
+        return nullptr;
+    }
+
+    auto *taskManager = findTaskManagerApplet(containment);
+
+    if (!taskManager) {
+        return nullptr;
+    }
+
+    return PlasmaQuick::AppletQuickItem::itemForApplet(taskManager);
+}
